package dev.duohome.hingelab

/** Observations apply to the tested firmware, not a compatibility promise. */
object ResearchModes {
    fun summary(mode: Int): String = when(mode) {
        86 -> "Точный угол из FoldInteractive + раннее событие TENT. Режим 4 сохраняет внутренний экран главным; импульс питания 700 мс сокращает провал при переключении. Лучший субъективный результат, но чёрное мигание и вспышка обоев остаются."
        71 -> "Классический 0.18: два экрана и восстановление источника угла после системной отмены. Угол возвращается, но повторное включение вызывает мигание. Базовый вариант исследования."
        88 -> "Обычное окно вместо Presentation переживает потерю FLAG_REAR. Автоматическое закрытие окна устранено, но физическая смена дисплеев всё равно прерывает картинку. Визуального улучшения не получено."
        87 -> "Заранее готовит кадр и сохраняет старое окно до замены. Первый пустой кадр сокращён; Samsung может сам закрыть Presentation. Устойчивого улучшения относительно 86 нет."
        85 -> "Постоянный режим 5: внешний экран главный, оба включены. Переходы без заметного мигания наблюдались; точный угол и анимация здесь не проверяются. Внутренний экран остаётся включённым даже в сложенном телефоне на время теста."
        84 -> "События DeviceState заменяют опрос dumpsys. Подтверждение режима сократилось до нескольких миллисекунд; физическое появление изображения не ускорилось сопоставимо."
        83 -> "Прямой запрос состояния с флагом, используемым камерой, без отдельных команд питания. Запрос быстрее старого опроса; мигание сохраняется."
        81 -> "Убирает power-reset из классической схемы. Уменьшилось число заметных переключений, но проблема передачи картинки не устранена."
        82 -> "Включает два экрана только во время движения: вход по углу ≤150° или TENT, выход по CLOSED либо свежему углу ≥178°. Опрос dumpsys добавляет задержку; в покое обычный режим."
        79 -> "Режим 5 сохраняет внешний экран главным при включении внутреннего. Передача экранов плавнее, но рабочий источник точного угла через внутренние обои не подтверждён."
        77 -> "Раннее состояние TENT сообщает о начале раскрытия раньше публичного значения 90°. Позволяет включать режим 4 из сложенного телефона без кнопки; системное мигание остаётся."
        78 -> "Вариант мягкой перспективы правой половины внутреннего экрана. Меняет художественный эффект, а не источник угла или ограничения дисплеев."
        76 -> "Проекция удерживает больше содержимого в кадре в диапазоне 55–180°. Это визуальная альтернатива; управление экранами классическое."
        74 -> "Правая половина внутреннего экрана раскрывается в диапазоне 55–175°. Проверяет геометрию эффекта независимо от механизма переключения."
        72 -> "Объединяет восстановление 0.18 с передачей сохранённого кадра Compat. Гипотеза плавной передачи изображения не дала лучшего результата на тестовом устройстве."
        70 -> "Адаптация цепочки Z Fold Duo: пробуждение обоев, восстановление подписки и переходы по углу. На проверенной прошивке не устранила зависание после закрытия и мигание. Авторство исходных компонентов указано в лицензиях."
        69 -> "Ранняя передача изображения версии 0.19. Сохранена как отрицательный контроль: после полного закрытия возможна потеря обновлений угла."
        else -> "Архивная проверка датчика и дисплеев. Постоянное значение угла само по себе не подтверждает рабочую подписку."
    }
}
